script:
default_currency = frappe.db.get_single_value("Global Defaults", "default_currency")
currencies = frappe.get_all("Currency", filters={"enabled": 1}, pluck="name")
today = frappe.utils.today()

settings = frappe.get_doc("Currency Exchange Settings")

for currency in currencies:
    if currency == default_currency:
        continue

    # Build params dari Currency Exchange Settings
    params = {}
    for row in settings.req_params:
        params[row.key] = row.value.replace("{from_currency}", currency).replace("{to_currency}", default_currency).replace("{transaction_date}", today)

    api_url = settings.api_endpoint.replace("{from_currency}", currency).replace("{to_currency}", default_currency).replace("{transaction_date}", today)

    response = frappe.make_get_request(api_url, params=params)

    # Traverse result_key dari settings
    value = response
    for res_key in settings.result_key:
        key = res_key.key.replace("{from_currency}", currency).replace("{to_currency}", default_currency)
        value = value[key]

    rate = frappe.utils.flt(value)

    if rate:
        existing = frappe.db.get_value("Currency Exchange", {
            "from_currency": currency,
            "to_currency": default_currency,
            "date": today
        }, "name")

        if existing:
            frappe.db.set_value("Currency Exchange", existing, "exchange_rate", rate)
        else:
            doc = frappe.get_doc({
                "doctype": "Currency Exchange",
                "from_currency": currency,
                "to_currency": default_currency,
                "date": today,
                "exchange_rate": rate,
                "for_buying": 1,
                "for_selling": 1
            })
            doc.insert(ignore_permissions=True)

frappe.db.commit()
